    return (shapes.length > 0 ? shapes : [el]) as Styled[];
  });
}

function stateOf(el: Styled, look: Look, reduce: boolean): Drawn {
  let d = drawn.get(el);
  if (!d) {
    const popped = pops(look);
    if (
      popped &&
      look.kind === 'check' &&
      el instanceof HTMLElement &&
      getComputedStyle(el).display === 'inline'
    )
      el.style.display = 'inline-block';
    d = {
      mode: popped
        ? 'pop'
        : el instanceof SVGGeometryElement
          ? 'stroke'
          : 'fade',
      from: look.kind === 'dot' ? 0 : POP_FROM,
      blur: look.kind === 'dot' ? 0 : POP_BLUR,
      progress: motionValue(1),
      opacity: Number(getComputedStyle(el).opacity),
      inlineOpacity: el.style.opacity,
      inlineTransform: el.style.transform,
      inlineFilter: el.style.filter,
      dash: DASH_ATTRIBUTES.map((name) => el.getAttribute(name)),
      reduce,
      controls: null,
      unsubscribe: () => {},
    };
    const state = d;
    d.unsubscribe = d.progress.on('change', (p) => write(el, state, p));
    drawn.set(el, d);
  }
  d.reduce = reduce;
  return d;
}

function forget(content: Element[]) {
  for (const el of content) {
    for (const target of [el, ...Array.from(el.querySelectorAll(SHAPES))]) {
      const d = drawn.get(target);
      if (!d) continue;
      d.controls?.stop();
      d.unsubscribe();
      write(target as Styled, d, 1);
      drawn.delete(target);
    }
  }
}

const anyShown = (targets: Element[]) =>
  targets.some((el) => (drawn.get(el)?.progress.get() ?? 0) > 0);

function animateTo(
  targets: Styled[],
  look: Look,
  shown: boolean,
  transition: Transition,
  reduce: boolean,
): Promise<void> {
  const runs = targets.map((el) => {
    const fresh = !drawn.has(el);
    const d = stateOf(el, look, reduce);
    d.controls?.stop();
    if (fresh && shown) d.progress.jump(0);
    const controls = animate(d.progress, shown ? 1 : 0, transition);
    d.controls = controls;
    return controls;
  });
  return Promise.all(runs).then(() => undefined);
}

function setNow(
  targets: Styled[],
  look: Look,
  shown: boolean,
  reduce: boolean,
) {
  for (const el of targets) {
    const d = stateOf(el, look, reduce);
    d.controls?.stop();
    d.controls = null;
    if (d.progress.get() === (shown ? 1 : 0)) write(el, d, shown ? 1 : 0);
    else d.progress.jump(shown ? 1 : 0);
  }
}

type IndicatorHandle = {
  element: HTMLElement;
  toggle: (shown: boolean, animated: boolean) => void;
  isShown: () => boolean;
};

type Coordinate = (handle: IndicatorHandle, shown: boolean) => void;

function mergeRefs<T>(
  ...refs: (React.Ref<T> | undefined)[]
): React.RefCallback<T> {
  return (node) => {
    const cleanups = refs.map((ref) => {
      if (typeof ref === 'function') return ref(node);
      if (ref) ref.current = node;
      return undefined;
    });
    return () => {
      cleanups.forEach((cleanup, i) => {
        const ref = refs[i];
        if (typeof cleanup === 'function') cleanup();
        else if (typeof ref === 'function') ref(null);
        else if (ref) ref.current = null;
      });
    };
  };
}

function contentOf(indicator: Element) {
  return Array.from(indicator.children).filter((child) => !ghosts.has(child));
}

type IndicatorContentProps = React.ComponentPropsWithRef<'span'> &
  IndicatorAnimationProps & {
    as?: 'span' | 'div';
    kind: IndicatorKind;
    animation?: CheckAnimation;
    checked: boolean;
    indeterminate?: boolean;
    coordinate?: Coordinate;
    animateOnMount?: boolean | (() => boolean);
  };

function IndicatorContent({
  as: Element = 'span',
  kind,
  animation = 'draw',
  checked,
  indeterminate = false,
  transition,
  exitTransition,
  coordinate,
  animateOnMount: animateOnMountProp,
  ref,
  style,
  ...props
}: IndicatorContentProps) {
  const localRef = React.useRef<HTMLSpanElement>(null);
  const [isPresent, safeToRemove] = usePresence();
  const presenceInitial = React.use(PresenceContext)?.initial !== false;
  const animateOnMount = animateOnMountProp ?? presenceInitial;
  const reduce = useShouldReduceMotion();
  const { enter, exit } = useIndicatorTransitions(kind, animation, {
    transition,
    exitTransition,
  });
  const visible = checked && isPresent;
  const lastRef = React.useRef<{
    visible: boolean;
    animation: CheckAnimation;
    content: Element[];
  } | null>(null);
  const runRef = React.useRef(0);
  const [hideFirst] = React.useState(
    () => !checked || animateOnMount !== false,
  );

  React.useLayoutEffect(() => {
    const element = localRef.current;
    const last = lastRef.current;
    if (!element) {
      if (!isPresent) safeToRemove?.();
      return;
    }
    const content = contentOf(element);
    lastRef.current = { visible, animation, content };
    const look = { kind, animation };
    const targets =
      content.length > 0 ? targetsOf(content, look) : [element as Styled];
    const enterTransition = indeterminate ? { ...enter, delay: 0 } : enter;
    const handle: IndicatorHandle = {
      element,
      toggle: (shown, animated) => {
        if (!animated) setNow(targets, look, shown, reduce);
        else
          void animateTo(
            targets,
            look,
            shown,
            shown ? enterTransition : exit,
            reduce,
          );
      },
      isShown: () => anyShown(targets),
    };

    if (!last) {
      element.style.opacity = '';
      const animated =
        typeof animateOnMount === 'function'
          ? animateOnMount()
          : animateOnMount;
      if (!visible || !animated) setNow(targets, look, visible, reduce);
      else if (coordinate) {
        setNow(targets, look, false, reduce);
        coordinate(handle, true);
      } else void animateTo(targets, look, true, enterTransition, reduce);
      return;
    }
    if (last.animation !== animation) {
      forget([element, ...last.content]);
      setNow(targets, look, visible, reduce);
      return;
    }
    if (last.visible === visible) {
      const fresh = targets.filter((el) => !drawn.has(el));
      if (visible && fresh.length > 0)
        void animateTo(fresh, look, true, enterTransition, reduce);
      return;
    }
    const id = ++runRef.current;
    if (coordinate && isPresent) {
      coordinate(handle, visible);
      return;
    }
    if (visible) {
      void animateTo(targets, look, true, enterTransition, reduce);
      return;
    }
    void animateTo(targets, look, false, exit, reduce).then(() => {
      if (runRef.current === id && !isPresent) safeToRemove?.();
    });
  });

  const mergedRef = React.useMemo(() => mergeRefs(ref, localRef), [ref]);
  return (
    <Element
      {...(props as React.ComponentProps<'span'>)}
      style={hideFirst ? { ...style, opacity: 0 } : style}
      ref={mergedRef}
    />
  );
}

type IndicatorPresenceProps = IndicatorContentProps & {
  keepMounted?: boolean;
};

function IndicatorPresence({ keepMounted, ...props }: IndicatorPresenceProps) {
  return (
    <AnimatePresence initial={false}>
      {(props.checked || keepMounted) && (
        <IndicatorContent key="indicator" {...props} />
      )}
    </AnimatePresence>
  );
}

function useRenderedIndicator(
  rootRef: React.RefObject<Element | null>,
  selector: string,
  kind: IndicatorKind,
  {
    checked,
    indeterminate = false,
    animation = 'draw',
  }: { checked: boolean; indeterminate?: boolean; animation?: CheckAnimation },
  transitions: IndicatorAnimationProps,
) {
  const reduce = useShouldReduceMotion();
  const { enter, exit } = useIndicatorTransitions(kind, animation, transitions);
  const lastRef = React.useRef<{
    checked: boolean;
    animation: CheckAnimation;
    content: Element[];
  } | null>(null);

  React.useLayoutEffect(() => {
    const indicator = rootRef.current?.querySelector(selector) ?? null;
    const content = indicator ? contentOf(indicator) : [];
    const previous = lastRef.current;
    lastRef.current = { checked, animation, content };
    const look = { kind, animation };
    const enterTransition = indeterminate ? { ...enter, delay: 0 } : enter;
    if (!previous) {
      setNow(targetsOf(content, look), look, true, reduce);
      return;
    }
    if (!indicator) return;
    if (previous.animation !== animation) {
      forget(previous.content);
      setNow(targetsOf(content, look), look, true, reduce);
      return;
    }
    if (previous.checked === checked) {
      const fresh = targetsOf(content, look).filter((el) => !drawn.has(el));
      if (checked && fresh.length > 0)
        void animateTo(fresh, look, true, enterTransition, reduce);
      return;
    }

    if (checked) {
      Array.from(indicator.children)
        .filter((child) => ghosts.has(child))
        .forEach((ghost) => ghost.remove());
      void animateTo(
        targetsOf(content, look),
        look,
        true,
        enterTransition,
        reduce,
      );
      return;
    }

    const kept = previous.content.filter((child) => child.isConnected);
    const copies = previous.content
      .filter((child) => !child.isConnected)
      .map((child) => {
        const copy = child.cloneNode(true) as Styled;
        ghosts.add(copy);
        copy.setAttribute('aria-hidden', 'true');
        copy.style.pointerEvents = 'none';
        indicator.appendChild(copy);
        return copy;
      });
    const exiting = targetsOf([...kept, ...copies], look);
    setNow(targetsOf(copies, look), look, true, reduce);
    void animateTo(exiting, look, false, exit, reduce).then(() =>
      copies.forEach((copy) => copy.remove()),
    );
  });
}

export {
  CHECK_TRANSITION,
  CHECK_EXIT_TRANSITION,
  POP_TRANSITION,
  POP_EXIT_TRANSITION,
  DOT_TRANSITION,
  IndicatorContent,
  IndicatorPresence,
  useRenderedIndicator,
  mergeRefs,
  animateTo,
  forget,
  targetsOf,
  type Look,
  type CheckAnimationProps,
  type Coordinate,
  type IndicatorHandle,
  type IndicatorKind,
  type IndicatorAnimationProps,
  type IndicatorContentProps,
  type IndicatorPresenceProps,
};

'use client';

import * as React from 'react';
import type { Transition } from 'motion/react';

import {
  motionTokens,
  toCssTiming,
  useShouldReduceMotion,
  useTempoTransition,
} from '../utils/motion';
import { curveFrom, velocityOf, INSTANT, type Run } from './momentum';

type Box = { x: number; y: number; width: number; height: number };

type IndicatorSnapshot = Box & {
  version: number;
  item: Element;
  className: string;
  attributes: Record<string, string>;
};

const SKIPPED_ATTRIBUTE =
  /^data-(slot|testid|animate-ui-.*|hovered|pressed|focused|focus-visible|highlighted|rac|react-aria-.*|key|radix-.*|composite-.*)$/;

const NONE = (value: string) => !value || value === 'none';

function layoutSizeOf(element: HTMLElement) {
  const style = getComputedStyle(element);
  let width = parseFloat(style.width);
  let height = parseFloat(style.height);
  if (!Number.isFinite(width) || !Number.isFinite(height))
    return { width: element.offsetWidth, height: element.offsetHeight };
  if (style.boxSizing !== 'border-box') {
    const px = (value: string) => parseFloat(value) || 0;
    width +=
      px(style.paddingLeft) +
      px(style.paddingRight) +
      px(style.borderLeftWidth) +
      px(style.borderRightWidth);
    height +=
      px(style.paddingTop) +
      px(style.paddingBottom) +
      px(style.borderTopWidth) +
      px(style.borderBottomWidth);
  }
  return { width, height };
}

function containerScale(container: HTMLElement, rect: DOMRect) {
  const { width, height } = layoutSizeOf(container);
  return {
    x: width && Math.abs(rect.width - width) > 0.01 ? rect.width / width : 1,
    y:
      height && Math.abs(rect.height - height) > 0.01
        ? rect.height / height
        : 1,
  };
}

function lengthOf(value: string, size: number) {
  if (value.endsWith('%')) return (parseFloat(value) / 100) * size;
  if (value.endsWith('px') || /^-?[\d.]+$/.test(value))
    return parseFloat(value);
  return null;
}

function untransform(element: Element, box: Box): Box {
  const style = getComputedStyle(element);
  if (NONE(style.translate) && NONE(style.scale) && NONE(style.transform))
    return box;
  if (!NONE(style.rotate)) return box;
  let [a, d, e, f] = [1, 1, 0, 0];
  if (!NONE(style.transform)) {
    const matrix = style.transform.match(/^matrix\(([^)]+)\)$/);
    if (!matrix) return box;
    const [ma = 1, mb = 0, mc = 0, md = 1, me = 0, mf = 0] = matrix[1]!
      .split(',')
      .map(Number);
    if (Math.abs(mb) > 1e-6 || Math.abs(mc) > 1e-6) return box;
    [a, d, e, f] = [ma, md, me, mf];
  }
  const scale = NONE(style.scale) ? [] : style.scale.split(/\s+/).map(Number);
  const sx = scale[0] ?? 1;
  const sy = scale[1] ?? sx;
  const [kx, ky] = [sx * a, sy * d];
  if (!kx || !ky || ![kx, ky].every(Number.isFinite)) return box;
  const width = box.width / kx;
  const height = box.height / ky;
  const [tX = '0px', tY = '0px'] = NONE(style.translate)
    ? []
    : style.translate.split(/\s+(?![^(]*\))/);
  const tx = lengthOf(tX, width);
  const ty = lengthOf(tY, height);
  const [oX = '0px', oY = '0px'] = style.transformOrigin.split(/\s+/);
  const ox = lengthOf(oX, width);
  const oy = lengthOf(oY, height);
  if (tx === null || ty === null || ox === null || oy === null) return box;
  return {
    x: box.x - ox - tx - sx * (e - a * ox),
    y: box.y - oy - ty - sy * (f - d * oy),
    width,
    height,
  };
}

function boxIn(
  container: HTMLElement,
  element: Element,
  untransformed = false,
): Box {
  const containerRect = container.getBoundingClientRect();
  const rect = element.getBoundingClientRect();
  const scale = containerScale(container, containerRect);
  const box = {
    x:
      (rect.left - containerRect.left) / scale.x -
      container.clientLeft +
      container.scrollLeft,
    y:
      (rect.top - containerRect.top) / scale.y -
      container.clientTop +
      container.scrollTop,
    width: rect.width / scale.x,
    height: rect.height / scale.y,
  };
  return untransformed ? untransform(element, box) : box;
}

function isTransformed(container: HTMLElement) {
  const rect = container.getBoundingClientRect();
  const { width, height } = layoutSizeOf(container);
  return (
    Math.abs(rect.width - width) > 0.01 || Math.abs(rect.height - height) > 0.01
  );
}

const sameBox = (a: Box, b: Box) =>
  Math.abs(a.x - b.x) < 0.01 &&
  Math.abs(a.y - b.y) < 0.01 &&
  Math.abs(a.width - b.width) < 0.01 &&
  Math.abs(a.height - b.height) < 0.01;

type BoxOf = (item: HTMLElement, container: HTMLElement) => Element;

type SlidingIndicatorConfig = {
  findActive: (container: HTMLElement) => HTMLElement | null;
  items: string;
  attributes: string[];
  style: { href: string; css: string };
  slot: string;
  reducedMotion?: 'jump' | 'fade';
  untransformed?: boolean;
  zIndex?: number;
  fadeBackground?: boolean;
};

function readSnapshot(
  container: HTMLElement,
  previous: IndicatorSnapshot | null,
  {
    copy,
    boxOf,
    config,
  }: { copy: boolean; boxOf?: BoxOf; config: SlidingIndicatorConfig },
): IndicatorSnapshot | null {
  const item = config.findActive(container);
  if (!item) return null;

  const box = boxIn(
    container,
    boxOf?.(item, container) ?? item,
    config.untransformed,
  );
  const attributes: Record<string, string> = {};
  if (copy) {
    for (const { name, value } of item.attributes) {
      if (name.startsWith('data-') && !SKIPPED_ATTRIBUTE.test(name))
        attributes[name] = value;
    }
  }
  const className = copy ? (item.getAttribute('class') ?? '') : '';

  if (
    previous &&
    previous.item === item &&
    sameBox(previous, box) &&
    previous.className === className &&
    JSON.stringify(previous.attributes) === JSON.stringify(attributes)
  )
    return previous;

  return {
    version:
      previous && previous.item !== item
        ? previous.version + 1
        : (previous?.version ?? 0),
    item,
    ...box,
    className,
    attributes,
  };
}

const isInIndicator = (node: Node, slot: string) =>
  node instanceof Element && node.closest(`[data-slot="${slot}"]`) !== null;

type Slide = {
  animations: Animation[];
  run: Run;
  to: Box;
};

const isRunning = (animation: Animation | undefined) =>
  animation !== undefined &&
  animation.playState !== 'finished' &&
  animation.playState !== 'idle';

const timeOf = (animation: Animation | undefined) =>
  Number(animation?.currentTime) || 0;

function startNow(animation: Animation) {
  animation.startTime = performance.now();
  return animation;
}

function boxOfSlide({ animations, run, to }: Slide): Box {
  const left = 1 - run.curve.at(timeOf(animations[0]));
  const [x = 0, y = 0, width = 0, height = 0] = run.offset;
  return {
    x: to.x + x * left,
    y: to.y + y * left,
    width: to.width + width * left,
    height: to.height + height * left,
  };
}

function onNextFrame(callback: () => void) {
  const frame = requestAnimationFrame(callback);
  return () => cancelAnimationFrame(frame);
}

const SLIDING_ATTRIBUTE = 'data-animate-ui-sliding';
const LEAVING_ATTRIBUTE = 'data-animate-ui-leaving';

const placement = (
  box: Box,
  zIndex: number,
  transition = 'none',
): React.CSSProperties => ({
  position: 'absolute',
  left: box.x,
  top: box.y,
  right: 'auto',
  bottom: 'auto',
  width: box.width,
  height: box.height,
  margin: 0,
  boxSizing: 'border-box',
  zIndex,
  pointerEvents: 'none',
  transition,
});

type Crossfades = {
  copies: Map<HTMLElement, Animation>;
  fadeIn: Animation | null;
};

type SlidingIndicatorOptions = {
  enabled?: boolean;
  transition?: Transition;
  surface?: {
    className?: string;
    style?: React.CSSProperties;
    slot?: string;
  };
  boxOf?: BoxOf;
};

function stopCrossfades(crossfades: Crossfades) {
  for (const [copy, animation] of crossfades.copies) {
    animation.cancel();
    copy.remove();
  }
  crossfades.copies.clear();
  crossfades.fadeIn?.cancel();
  crossfades.fadeIn = null;
}

const INDICATOR_TRANSITION: Transition = motionTokens.spring.selection;

function useSlidingIndicator(
  container: HTMLElement | null,
  config: SlidingIndicatorConfig,
  { enabled = true, transition, surface, boxOf }: SlidingIndicatorOptions = {},
) {
  const [snapshot, setSnapshot] = React.useState<IndicatorSnapshot | null>(
    null,
  );
  const copy = !surface;
  const slot = surface?.slot ?? config.slot;

  const boxOfRef = React.useRef(boxOf);
  const configRef = React.useRef(config);
  React.useLayoutEffect(() => {
    boxOfRef.current = boxOf;
    configRef.current = config;
  });

  React.useLayoutEffect(() => {
    if (!container || !enabled) return;
    if (getComputedStyle(container).position === 'static')
      container.style.position = 'relative';
    container.style.isolation = 'isolate';

    let reread = 0;
    let rereads = 0;
    const update = () => {
      setSnapshot((previous) =>
        readSnapshot(container, previous, {
          copy,
          boxOf: boxOfRef.current,
          config: configRef.current,
        }),
      );
      if (!isTransformed(container)) {
        rereads = 0;
        return;
      }
      if (reread || ++rereads > 90) return;
      reread = requestAnimationFrame(() => {
        reread = 0;
        update();
      });
    };
    const resize = new ResizeObserver(update);
    const observeItems = () => {
      resize.observe(container);
      for (const item of container.querySelectorAll<HTMLElement>(
        configRef.current.items,
      )) {
        resize.observe(item);
        const box = boxOfRef.current?.(item, container);
        if (box && box !== item) resize.observe(box);
      }
    };
    const mutations = new MutationObserver((records) => {
      if (records.every((r) => isInIndicator(r.target, slot))) return;
      observeItems();
      update();
    });
    mutations.observe(container, {
      subtree: true,
      childList: true,
      characterData: true,
      attributes: true,
      attributeFilter: configRef.current.attributes,
    });
    container.addEventListener('scroll', update, {
      capture: true,
      passive: true,
    });
    observeItems();
    update();

    return () => {
      mutations.disconnect();
      resize.disconnect();
      container.removeEventListener('scroll', update, { capture: true });
      cancelAnimationFrame(reread);
    };
  }, [container, enabled, copy, slot]);

  const visible = container && enabled ? snapshot : null;

  const slideTransition = useTempoTransition(
    transition ?? INDICATOR_TRANSITION,
  );
  const fade = toCssTiming(useTempoTransition(motionTokens.transition.fade));
  const color = toCssTiming(useTempoTransition(motionTokens.transition.color));
  const reduce = useShouldReduceMotion();
  const latestRef = React.useRef({
    slideTransition,
    fade,
    reduce,
    copy,
    slot,
    surface,
  });
  React.useLayoutEffect(() => {
    latestRef.current = { slideTransition, fade, reduce, copy, slot, surface };
  });

  const indicatorRef = React.useRef<HTMLSpanElement | null>(null);
  const slideRef = React.useRef<Slide | null>(null);
  const crossfadesRef = React.useRef<Crossfades>({
    copies: new Map(),
    fadeIn: null,
  });
  const restRef = React.useRef<{
    version: number;
    box: Box;
    className: string;
    attributes: Record<string, string>;
  } | null>(null);
  const paintedRef = React.useRef(false);
  React.useLayoutEffect(
    () => onNextFrame(() => (paintedRef.current = true)),
    [],
  );

  React.useLayoutEffect(() => {
    const element = indicatorRef.current;
    const slide = slideRef.current;
    const stop = () => {
      slide?.animations.forEach((animation) => animation.cancel());
      slideRef.current = null;
      element?.removeAttribute(SLIDING_ATTRIBUTE);
    };
    if (!element || !visible) {
      stop();
      stopCrossfades(crossfadesRef.current);
      restRef.current = null;
      return;
    }

    const to: Box = {
      x: visible.x,
      y: visible.y,
      width: visible.width,
      height: visible.height,
    };
    const rest = restRef.current;
    restRef.current = {
      version: visible.version,
      box: to,
      className: visible.className,
      attributes: visible.attributes,
    };
    const moving = slide !== null && isRunning(slide.animations[0]);
    if (
      !rest ||
      !paintedRef.current ||
      (visible.version === rest.version && !moving)
    ) {
      stop();
      return;
    }

    const from = moving ? boxOfSlide(slide) : rest.box;
    const velocity = moving
      ? velocityOf(slide.run, timeOf(slide.animations[0]))
      : [0, 0, 0, 0];
    const startTime = moving
      ? Math.max(
          Number(document.timeline.currentTime),
          Number(slide.animations[0]!.startTime),
        ) || performance.now()
      : performance.now();
    stop();
    const offset = [
      from.x - to.x,
      from.y - to.y,
      from.width - to.width,
      from.height - to.height,
    ];
    if (offset.every((value) => Math.abs(value) < 0.5)) return;
    if (typeof element.animate !== 'function') return;

    const { slideTransition, fade, reduce, copy, slot, surface } =
      latestRef.current;

    if (reduce && configRef.current.reducedMotion === 'fade') {
      const crossfades = crossfadesRef.current;
      if (fade.duration <= 0) {
        stopCrossfades(crossfades);
        return;
      }
