  reopen() {
    if (!this.dropped) return;
    this.dropped = false;
    show(this.node);
  }

  await(source: HandoffEntry | null) {
    this.pending = source;
  }

  addNested(node: HTMLElement) {
    show(node);
    this.nested.add(node);
    return () => {
      this.nested.delete(node);
