function measureRest(
  thumb: Thumb,
  x: number,
  width: number,
  withAnchor: boolean,
): Rest {
  const left = withoutTransitions(thumb, () => visualLeft(thumb)) - x;
  return {
    left,
    width,
    anchor: withAnchor ? growthAnchor(thumb, width) : 0,
  };
