function createThumbMotion(): ThumbMotion {
  return {
    x: motionValue(0),
    width: motionValue(0),
    stretched: false,
    unit: 1,
    lean: 0,
    shift: 0,
    natural: 0,
    rest: null,
    committed: null,
    controls: [],
    pending: null,
    run: 0,
  };
}

function snapped(m: ThumbMotion, width: number) {
  return m.natural + Math.round((width - m.natural) * m.unit) / m.unit;
